def _phantom_sys_final_norm_ts(ts):
    value = str(ts or "").strip()
    if not value:
        return ""
    value = value.replace("T", " ")
    value = re.sub(r"\.0+(?=Z?$)", "", value)
    if re.match(r"^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$", value):
        value += "Z"
    return value


